import json, pathlib, unittest
loader = unittest.TestLoader()
suite = loader.discover("tests/tooling", pattern="test_*.py")
def walk(value):
    if isinstance(value, unittest.TestSuite):
        for child in value:
            yield from walk(child)
    else:
        yield value.id()
names = sorted(walk(suite))
if loader.errors or any("_FailedTest" in name for name in names):
    raise RuntimeError("test discovery failed: " + repr(loader.errors))
print(json.dumps({"tests": names, "discovery_errors": loader.errors}))

